const sourcesConfig = $('Call WF-L0 Sources').all()[0].json.config || {};
const prefsConfig = $('Call WF-L0 Preferences').all()[0].json.config || {};
return [{ json: { aggregators: sourcesConfig.aggregators || [], queries: prefsConfig.queries || [], x_search_queries: prefsConfig.x_search_queries || [] } }];

const cfg = $input.first().json;
return (cfg.aggregators || [])
  .filter(a => a.enabled === true)
  .map(a => ({ json: { provider: a.provider, monthly_limit: a.monthly_limit } }));

return $input.all()
  .filter(i => i.json.used < i.json.monthly_limit)
  .map(i => ({ json: { ...i.json, remaining: i.json.monthly_limit - i.json.used } }));

// Same shared 'serpapi' quota (250/month total) covers both engines below --
// google_jobs (structured results, no LLM needed) and, weekly only, a plain
// google site:x.com search whose snippets need LLM extraction (see Route
// SerpApi Results). Running x_search daily would blow the shared budget --
// 7 job queries/day alone is ~210/month, leaving ~40/month of headroom.
const cfg = $('Combine Configs').all()[0].json;
const quota = $input.first().json;

const jobItems = (cfg.queries || []).map(q => ({ provider: 'serpapi', type: 'job', engine: 'google_jobs', query: q }));

const isWeeklyWindow = new Date().getUTCDay() === 0; // Sunday only
const xItems = isWeeklyWindow
  ? (cfg.x_search_queries || []).map(q => ({ provider: 'serpapi', type: 'x_search', engine: 'google', query: q }))
  : [];

const all = [...jobItems, ...xItems].slice(0, quota.remaining);
return all.map(j => ({ json: j }));

function mapScheduleType(s) {
  if (!s) return null;
  const t = s.toLowerCase();
  if (t.includes('intern')) return 'internship';
  if (t.includes('full')) return 'full_time';
  if (t.includes('part')) return 'part_time';
  if (t.includes('contract') || t.includes('temp')) return 'contract';
  return null;
}

function parseRelativeDate(s) {
  if (!s) return null;
  const m = s.match(/(\d+)\s+(hour|day|week|month)s?\s+ago/i);
  if (!m) return null;
  const n = parseInt(m[1], 10);
  const unit = m[2].toLowerCase();
  const ms = { hour: 3600000, day: 86400000, week: 604800000, month: 2592000000 }[unit];
  return new Date(Date.now() - n * ms).toISOString();
}

const queryItems = $('Build SerpApi Queries').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const resp = $input.all()[i].json;
  const q = queryItems[i].json;
  if (resp.statusCode !== 200) continue;
  let parsed;
  try {
    const raw = typeof resp.body === 'string' ? resp.body : resp.data;
    parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) {
    continue;
  }

  if (q.type === 'job') {
    const jobs = parsed.jobs_results || [];
    for (const j of jobs) {
      const ext = j.detected_extensions || {};
      out.push({
        json: {
          _route: 'direct',
          company: j.company_name,
          role: j.title,
          location: j.location || null,
          employment_type: mapScheduleType(ext.schedule_type),
          apply_url: j.source_link || j.share_link,
          source: 'serpapi',
          source_id: null,
          description: j.description || null,
          posted_date: parseRelativeDate(ext.posted_at)
        }
      });
    }
  } else {
    // x_search: only individual tweets (/status/<id>) are single postings --
    // profile/account pages (e.g. an aggregator account's bio) mash multiple
    // openings into one snippet and aren't reliably extractable as one job.
    const results = parsed.organic_results || [];
    for (const r of results) {
      if (!/\/status\/\d+/.test(r.link || '')) continue;
      out.push({
        json: {
          _route: 'llm',
          title: r.title || '',
          snippet: r.snippet || '',
          link: r.link
        }
      });
    }
  }
}

return out;

const ctx = $('Filter LLM Candidates').all()[$itemIndex].json;

const content = $json.content || [];
const textBlock = content.find(b => b.type === 'text');
const rawText = textBlock ? textBlock.text : '';

let parsed;
try {
  const cleaned = (rawText || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  return { json: { skip: true } };
}

if (parsed.not_a_posting || !parsed.company || !parsed.role) {
  return { json: { skip: true } };
}

return {
  json: {
    skip: false,
    _route: 'direct',
    company: parsed.company,
    role: parsed.role,
    location: parsed.location || null,
    employment_type: parsed.employment_type || null,
    apply_url: ctx.link,
    source: 'serpapi_x',
    source_id: null,
    description: parsed.description || null,
    posted_date: null
  }
};

// JSearch's real response shape has never been verified against a live call --
// no RapidAPI credential exists for it yet (see CLAUDE.md "Blocked on the
// user"). This branch stays inert until sources.json's jsearch entry is
// flipped to enabled AND a real httpHeaderAuth credential is created --
// guessing the parser now would repeat the exact mistake this project has
// deliberately avoided everywhere else. Do not enable without testing first.
const quota = $input.first().json;
const queries = ($('Combine Configs').all()[0].json.queries || []).slice(0, quota.remaining);
return queries.map(q => ({ json: { provider: 'jsearch', query: q } }));

// Unreachable in production while jsearch stays disabled in sources.json --
// see the note on Build JSearch Queries. Left unimplemented deliberately
// rather than guessing a response shape that's never been observed live.
return [];

const dedupOutputs = $input.all();
const originals = $('Call WF-L1').all();
const toScore = [];
for (let i = 0; i < dedupOutputs.length; i++) {
  if (dedupOutputs[i].json.was_inserted === true) {
    toScore.push({ json: originals[i].json });
  }
}
return toScore;

let serpapiCalls = 0, jsearchCalls = 0;
try { serpapiCalls = $('Build SerpApi Queries').all().length; } catch (e) {}
try { jsearchCalls = $('Build JSearch Queries').all().length; } catch (e) {}

const out = [];
const period = new Date().toISOString().slice(0, 7);
if (serpapiCalls > 0) out.push({ json: { provider: 'serpapi', period_month: period, calls_made: serpapiCalls, monthly_limit: 250 } });
if (jsearchCalls > 0) out.push({ json: { provider: 'jsearch', period_month: period, calls_made: jsearchCalls, monthly_limit: 200 } });
return out;

const items = $input.all();
const fetched = items.length;
const inserted = items.filter(i => i.json.was_inserted === true).length;
return [{ json: { fetched, new_count: inserted } }];
